CustomField.formula:
CASE(Estatus__c,
    "Cancelada", "Cancelada",
IF(ISBLANK(Vigencia_hasta__c), "Sin fecha",
			IF(Vigencia_desde__c > Vigencia_hasta__c, "Vigor",
						IF(Vigencia_hasta__c >= TODAY(),"Vigor",
									IF(Dias_Gracia__c > 0,"Vencida",
												IF(Vigencia_hasta__c >= (TODAY() - Dias_Gracia__c),"En Gracia","Cancelada"))
					)
		)
)
					)
